const queryResponse = $node['Fetch GSC Query Data'].json;
const pageResponse = $node['Fetch GSC Page Data'].json;

const queryRows = queryResponse.rows || [];
const pageRows = pageResponse.rows || [];

// Process query data
const queries = queryRows.map(row => ({
  query: row.keys[0],
  page: row.keys[1],
  clicks: row.clicks,
  impressions: row.impressions,
  ctr: Math.round(row.ctr * 10000) / 100,
  position: Math.round(row.position * 10) / 10
}));

// Top queries by impressions
const topQueries = [...queries].sort((a, b) => b.impressions - a.impressions).slice(0, 50);

// Quick wins: high impressions, low CTR, position 4-20
const quickWins = queries.filter(q => 
  q.impressions > 50 && q.ctr < 3 && q.position >= 4 && q.position <= 20
).sort((a, b) => b.impressions - a.impressions).slice(0, 20);

// Rising queries: position improving (would need historical data)
const highPotential = queries.filter(q =>
  q.position <= 10 && q.ctr < 5 && q.impressions > 100
).slice(0, 10);

// Page performance
const pagePerformance = {};
for (const row of pageRows) {
  const page = row.keys[0];
  if (!pagePerformance[page]) {
    pagePerformance[page] = { page, clicks: 0, impressions: 0, devices: {} };
  }
  pagePerformance[page].clicks += row.clicks;
  pagePerformance[page].impressions += row.impressions;
  pagePerformance[page].devices[row.keys[1]] = {
    clicks: row.clicks,
    impressions: row.impressions,
    ctr: Math.round(row.ctr * 10000) / 100,
    position: Math.round(row.position * 10) / 10
  };
}

const topPages = Object.values(pagePerformance)
  .sort((a, b) => b.clicks - a.clicks)
  .slice(0, 20);

return [{
  json: {
    date: new Date(Date.now() - 2*24*60*60*1000).toISOString().split('T')[0],
    summary: {
      total_queries: queries.length,
      total_clicks: queries.reduce((s, q) => s + q.clicks, 0),
      total_impressions: queries.reduce((s, q) => s + q.impressions, 0),
      avg_ctr: queries.length > 0 ? Math.round(queries.reduce((s, q) => s + q.ctr, 0) / queries.length * 100) / 100 : 0,
      avg_position: queries.length > 0 ? Math.round(queries.reduce((s, q) => s + q.position, 0) / queries.length * 10) / 10 : 0
    },
    top_queries: topQueries.slice(0, 20),
    quick_wins: quickWins,
    high_potential: highPotential,
    top_pages: topPages
  }
}];

